insert into public.regions (id, name, description, sort, lat, lng) values
('svaneti','სვანეთი','მესტია, უშგული და კავკასიონის უმაღლესი მწვერვალები: კოშკები, მყინვარები და საქართველოს ყველაზე პოპულარული ტრეკები.',1,43.0,42.8),
('kazbegi','ყაზბეგი','ხევი და ყაზბეგის მთა: გერგეტის სამება, ჯუთა, ჭაუხი, თრუსო და ვულკანური კელის ზეგანი.',2,42.62,44.6),
('khevsureti','ხევსურეთი','შატილი, მუცო, როშკა და აბუდელაურის ტბები — მკაცრი და ლამაზი მთიანეთი.',3,42.6,45.0),
('tusheti','თუშეთი','ომალო, დართლო და პირიქითა: საქართველოს ყველაზე იზოლირებული მთის კუთხე, მხოლოდ ზაფხულში მისასვლელი.',4,42.42,45.55),
('mtiuleti','მთიულეთი და გუდაური','ხადის ხეობა, ლომისა და არაგვის ხეობა საქართველოს სამხედრო გზის გასწვრივ.',5,42.43,44.55),
('racha','რაჭა-ლეჩხუმი','ხვამლი, შაორი და რაჭის კავკასიონი — მშვიდი მთები ტყეებით და ხედებით.',6,42.55,43.1),
('imereti','იმერეთი','კანიონები, ჩანჩქერები და მღვიმეები ქუთაისის ახლოს — ოჯახური სასეირნო ბილიკები.',7,42.35,42.65),
('samegrelo','სამეგრელო','მარტვილის კანიონი და ეგრისის ქედის ველური მაღალმთიანი ტბები.',8,42.55,42.2),
('kakheti','კახეთი','ლაგოდეხის ტყეები და ტბები, ვაშლოვანის ''სავანა'' და ალაზნის ველი.',9,41.8,46.1),
('tbilisi','თბილისი და შემოგარენი','ერთდღიანი ლაშქრობები დედაქალაქიდან: მთაწმინდა, მცხეთა, ბირთვისი, დაშბაში.',10,41.72,44.78),
('borjomi','ბორჯომი და სამცხე-ჯავახეთი','ბორჯომ-ხარაგაულის ეროვნული პარკი, ბაკურიანი და ჯავახეთის ზეგანი.',11,41.8,43.3),
('adjara','აჭარა','მტირალას წვიმიანი ტყეები, მაჭახელა და კინტრიშის მთები ზღვის ახლოს.',12,41.65,42.0),
('guria','გურია','ბახმაროს ალპური კურორტი და ქედები, საიდანაც შავი ზღვა ჩანს.',13,41.85,42.3)
